#!/usr/bin/env python3
"""Predict four circRNA CS probability scores with embedded fitted models.

Usage:
    python3 predictCS.py INPUT_TXT OUTPUT_TXT
"""

from __future__ import annotations

import base64
import csv
import math
import numbers
import os
from pathlib import Path
import sys
import tempfile
from typing import Any
import zlib

try:
    import numpy as np
    import xgboost as xgb
except ImportError as error:
    missing_package = getattr(error, "name", "unknown")
    raise SystemExit(
        "Missing required Python package: "
        f"{missing_package}. Install dependencies with: "
        "python3 -m pip install numpy xgboost"
    ) from error


