OUTPUT_COLUMNS = [
    "circRNA_id",
    "XGBoost_CS-R_score",
    "XGBoost_CS-C_score",
    "ElasticNet_CS-R_score",
    "ElasticNet_CS-C_score",
]


def is_missing(value: Any) -> bool:
    """Return True for blank, whitespace-only, and NaN values."""
    return (
        value is None
        or (isinstance(value, str) and not value.strip())
        or (
            isinstance(value, numbers.Real)
            and not isinstance(value, bool)
            and math.isnan(float(value))
        )
    )


def read_input_text(
    input_file: Path,
) -> tuple[list[str], dict[str, np.ndarray]]:
    """Read and validate a tab-delimited circRNA predictor text file."""
    with input_file.open("r", encoding="utf-8-sig", newline="") as handle:
        rows = csv.reader(handle, delimiter="\t", quotechar='"')
        try:
            raw_header = next(rows)
        except StopIteration as error:
            raise ValueError("The new-input text file contains no rows.") from error

        header = [value.strip() for value in raw_header]
        named_header = [name for name in header if name]
        if len(set(named_header)) != len(named_header):
            duplicates = sorted(
                {name for name in named_header if named_header.count(name) > 1}
            )
            raise ValueError(
                "New-input column names must be unique. Duplicate column(s): "
                + ", ".join(duplicates)
            )

        column_index = {name: index for index, name in enumerate(header) if name}
        required_columns = ["circRNA_id", *FEATURE_MAP.values()]
        missing_columns = [
            name for name in required_columns if name not in column_index
        ]
        if missing_columns:
            raise ValueError(
                "New input is missing column(s): " + ", ".join(missing_columns)
            )

        circRNA_ids: list[str] = []
        predictor_values = {
            feature_name: []
            for feature_name in FEATURE_MAP.values()
        }
        for text_row_number, row in enumerate(rows, start=2):
            if not any(value.strip() for value in row):
                continue
            if len(row) > len(header) and any(
                value.strip() for value in row[len(header):]
            ):
                raise ValueError(
                    f"New-input row {text_row_number} contains more fields "
                    "than the header."
                )
            row_values = row + [""] * max(0, len(header) - len(row))
            circRNA_id = row_values[column_index["circRNA_id"]].strip()
            if not circRNA_id:
                raise ValueError(
                    "New-input circRNA_id values cannot be missing or blank "
                    f"(text row {text_row_number})."
                )
            circRNA_ids.append(circRNA_id)

            for feature_name in FEATURE_MAP.values():
                value = row_values[column_index[feature_name]]
                if is_missing(value):
                    predictor_values[feature_name].append(np.nan)
                    continue
                try:
                    numeric_value = float(value.strip())
                except ValueError as error:
                    raise ValueError(
                        f"New-input predictor '{feature_name}' contains a "
                        f"nonnumeric value at text row {text_row_number}: "
                        f"{value!r}. Use an empty tab-delimited field for a "
                        "missing value."
                    ) from error
                if math.isnan(numeric_value):
                    raise ValueError(
                        f"New-input predictor '{feature_name}' contains a "
                        f"nonnumeric value at text row {text_row_number}: "
                        f"{value!r}. Use an empty tab-delimited field for a "
                        "missing value."
                    )
                predictor_values[feature_name].append(numeric_value)

    if not circRNA_ids:
        raise ValueError("The new-input text file contains no data rows.")
    if len(circRNA_ids) != len(set(circRNA_ids)):
        raise ValueError("New-input circRNA_id values must be unique.")

    predictors = {
        name: np.asarray(values, dtype=float)
        for name, values in predictor_values.items()
    }
    return circRNA_ids, predictors


def load_embedded_booster(mode_name: str) -> xgb.Booster:
    """Load one embedded zlib-compressed UBJ XGBoost model."""
    compressed = base64.b64decode(
        XGBOOST_MODELS_ZLIB_BASE64[mode_name],
        validate=True,
    )
    model_bytes = zlib.decompress(compressed)
    booster = xgb.Booster()
    try:
        booster.load_model(bytearray(model_bytes))
    except (TypeError, xgb.core.XGBoostError):
        temporary_path: str | None = None
        try:
            with tempfile.NamedTemporaryFile(
                suffix=".ubj",
                delete=False,
            ) as temporary_file:
                temporary_file.write(model_bytes)
                temporary_path = temporary_file.name
            booster.load_model(temporary_path)
        finally:
            if temporary_path and os.path.exists(temporary_path):
                os.unlink(temporary_path)
    return booster


def predict_xgboost(
    mode_name: str,
    predictors: dict[str, np.ndarray],
) -> tuple[np.ndarray, int]:
    """Predict complete rows and leave incomplete rows missing."""
    feature_names = [
        FEATURE_MAP[feature_id]
        for feature_id in FEATURE_MODES[mode_name]
    ]
    matrix = np.column_stack([predictors[name] for name in feature_names])
    complete_rows = np.isfinite(matrix).all(axis=1)
    scores = np.full(matrix.shape[0], np.nan, dtype=float)
    if complete_rows.any():
        predicted_scores = load_embedded_booster(mode_name).predict(
            xgb.DMatrix(
                matrix[complete_rows],
                feature_names=feature_names,
                missing=np.nan,
            )
        )
        predicted_scores = np.asarray(predicted_scores, dtype=float)
        if predicted_scores.shape != (int(complete_rows.sum()),):
            raise ValueError(f"Invalid XGBoost scores for mode {mode_name}.")
        scores[complete_rows] = predicted_scores

    valid_scores = scores[complete_rows]
    if (
        not np.isfinite(valid_scores).all()
        or (valid_scores < 0).any()
        or (valid_scores > 1).any()
    ):
        raise ValueError(f"Invalid XGBoost scores for mode {mode_name}.")
    return scores, int((~complete_rows).sum())


def stable_expit(values: np.ndarray) -> np.ndarray:
    """Calculate logistic probabilities without exponential overflow."""
    probabilities = np.empty_like(values, dtype=float)
    nonnegative = values >= 0
    probabilities[nonnegative] = 1.0 / (
        1.0 + np.exp(-values[nonnegative])
    )
    exponentials = np.exp(values[~nonnegative])
    probabilities[~nonnegative] = exponentials / (1.0 + exponentials)
    return probabilities


def predict_elastic_net(
    mode_name: str,
    predictors: dict[str, np.ndarray],
) -> tuple[np.ndarray, int]:
    """Predict complete rows and leave incomplete rows missing."""
    model = ELASTIC_NET_MODELS[mode_name]
    coefficients = model["coefficients"]
    feature_names = list(coefficients)
    matrix = np.column_stack([predictors[name] for name in feature_names])
    complete_rows = np.isfinite(matrix).all(axis=1)
    scores = np.full(matrix.shape[0], np.nan, dtype=float)
    if complete_rows.any():
        coefficient_vector = np.asarray(
            [coefficients[name] for name in feature_names],
            dtype=float,
        )
        linear_predictor = (
            float(model["intercept"])
            + matrix[complete_rows] @ coefficient_vector
        )
        scores[complete_rows] = stable_expit(linear_predictor)

    valid_scores = scores[complete_rows]
    if (
        not np.isfinite(valid_scores).all()
        or (valid_scores < 0).any()
        or (valid_scores > 1).any()
    ):
        raise ValueError(f"Invalid Elastic Net scores for mode {mode_name}.")
    return scores, int((~complete_rows).sum())


def save_predictions(
    output_file: Path,
    circRNA_ids: list[Any],
    score_columns: dict[str, np.ndarray],
) -> None:
    """Write only the prediction columns to a tab-delimited text file."""
    output_file.parent.mkdir(parents=True, exist_ok=True)
    with output_file.open("w", encoding="utf-8", newline="") as handle:
        writer = csv.writer(
            handle,
            delimiter="\t",
            lineterminator="\n",
            quoting=csv.QUOTE_MINIMAL,
        )
        writer.writerow(OUTPUT_COLUMNS)
        for row_index, circRNA_id in enumerate(circRNA_ids):
            output_row: list[Any] = [circRNA_id]
            for column_name in OUTPUT_COLUMNS[1:]:
                score = float(score_columns[column_name][row_index])
                output_row.append("." if math.isnan(score) else score)
            writer.writerow(output_row)


def parse_arguments(arguments: list[str]) -> tuple[Path, Path]:
    """Parse the same positional arguments and defaults as predictCS.R."""
    if len(arguments) > 2:
        raise ValueError("Usage: predictCS.py INPUT_TXT OUTPUT_TXT")
    input_file = Path(arguments[0]) if len(arguments) >= 1 else Path(
        "input", "circRNA_testdat.txt"
    )
    output_file = Path(arguments[1]) if len(arguments) >= 2 else Path(
        "output", "circRNA_testdat_predictCS.txt"
    )
    return input_file, output_file


def main(arguments: list[str]) -> int:
    """Run all four predictors and save a prediction-only text file."""
    input_file, output_file = parse_arguments(arguments)
    if not input_file.is_file():
        raise FileNotFoundError(f"Required input text file not found: {input_file}")
    if input_file.resolve() == output_file.resolve():
        raise ValueError("Output text file must differ from the input text file.")

    circRNA_ids, predictors = read_input_text(input_file)
    score_columns = {}
    skip_messages = []
    for mode_name in ("CS-R", "CS-C"):
        scores, skipped_rows = predict_xgboost(mode_name, predictors)
        score_columns[f"XGBoost_{mode_name}_score"] = scores
        skip_messages.append(
            f"XGBoost {mode_name}: skipped {skipped_rows} row(s) "
            "with missing required features; score will be '.'."
        )

    for mode_name in ("CS-R", "CS-C"):
        scores, skipped_rows = predict_elastic_net(mode_name, predictors)
        score_columns[f"ElasticNet_{mode_name}_score"] = scores
        skip_messages.append(
            f"Elastic Net {mode_name}: skipped {skipped_rows} row(s) "
            "with missing required features; score will be '.'."
        )
    print("\n".join(skip_messages), file=sys.stderr)

    save_predictions(output_file, circRNA_ids, score_columns)
    print(
        f"Saved four probability scores for {len(circRNA_ids)} circRNAs "
        f"to {output_file}.",
        file=sys.stderr,
    )
    return 0


if __name__ == "__main__":
    try:
        raise SystemExit(main(sys.argv[1:]))
    except Exception as error:
        raise SystemExit(f"Error: {error}") from error
